import { markHostedFirstVisibleReply } from "../../internal/hosted-execution-latency.js";
import { deleteMessage, postMessage, updateMessage } from "./api.js";
function activeProgressTs(state) {
    const ts = state.progressTs;
    return ts == null || ts === "" ? null : ts;
}
export function createProgressDelivery(deps) {
    const { botToken, getLog } = deps;
    const clear = async (args) => {
        const state = args.channel.state;
        const ts = activeProgressTs(state);
        state.progressTs = null;
        if (ts === null || state.channelId === null) {
            return;
        }
        const deleted = await deleteMessage({
            botToken,
            channel: state.channelId,
            ts,
        });
        if (!deleted.ok) {
            getLog().warn("progress delete failed", {
                error: deleted.error,
                channel: state.channelId,
                progress_ts: ts,
            });
        }
    };
    return {
        async upsert(args) {
            const state = args.channel.state;
            if (state.channelId === null || state.threadTs === null || args.text === "") {
                return;
            }
            const existing = activeProgressTs(state);
            if (existing !== null) {
                const updated = await updateMessage({
                    botToken,
                    channel: state.channelId,
                    ts: existing,
                    text: args.text,
                });
                if (updated.ok) {
                    markHostedFirstVisibleReply({
                        outcome: "progress_update",
                        deliverySurface: "slack",
                    });
                    return;
                }
                getLog().warn("progress update failed; posting a new message", {
                    error: updated.error,
                    channel: state.channelId,
                    thread_ts: state.threadTs,
                    progress_ts: existing,
                });
                await clear({ channel: args.channel });
            }
            try {
                const posted = await postMessage({
                    botToken,
                    channel: state.channelId,
                    threadTs: state.threadTs,
                    text: args.text,
                });
                state.progressTs = posted.ts;
                markHostedFirstVisibleReply({
                    outcome: "progress_update",
                    deliverySurface: "slack",
                });
            }
            catch (error) {
                getLog().warn(`progress post failed: ${error instanceof Error ? error.message : String(error)}`, {
                    channel: state.channelId,
                    thread_ts: state.threadTs,
                });
            }
        },
        async replace(args) {
            const state = args.channel.state;
            const ts = activeProgressTs(state);
            if (ts === null || state.channelId === null || args.text === "") {
                return false;
            }
            const updated = await updateMessage({
                botToken,
                channel: state.channelId,
                ts,
                text: args.text,
            });
            if (!updated.ok) {
                getLog().warn("progress replace failed", {
                    error: updated.error,
                    channel: state.channelId,
                    progress_ts: ts,
                });
                return false;
            }
            state.lastPostedText = args.text;
            state.lastBotMessageTs = ts;
            state.progressTs = null;
            markHostedFirstVisibleReply({
                outcome: "progress_update",
                deliverySurface: "slack",
            });
            return true;
        },
        clear,
    };
}
